<?php
namespace App\Http\Controllers;
use App\Support\UserDataScope; use Carbon\Carbon; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule;
class LeaveRequestController extends Controller {
 public function index(Request $r){$u=$r->user();$ids=UserDataScope::studentIds($u);$requests=DB::table('leave_requests')->join('users as students','students.id','=','leave_requests.student_id')->join('users as submitters','submitters.id','=','leave_requests.submitted_by')->leftJoin('users as reviewers','reviewers.id','=','leave_requests.reviewed_by')->whereIn('leave_requests.student_id',$ids)->select('leave_requests.*','students.name as student_name','submitters.name as submitter_name','reviewers.name as reviewer_name')->latest('leave_requests.created_at')->get();$children=$u->role==='parent'?DB::table('users')->whereIn('id',$ids)->orderBy('name')->get():collect();return view('attendance.leave-requests',compact('requests','children','u'));}
 public function store(Request $r){$u=$r->user();$allowed=UserDataScope::studentIds($u);$d=$r->validate(['student_id'=>'nullable|integer|exists:users,id','type'=>['required',Rule::in(['izin','sakit'])],'date_start'=>'required|date','date_end'=>'required|date|after_or_equal:date_start','reason'=>'required|string|max:2000','evidence'=>'nullable|file|mimes:jpg,jpeg,png,webp,pdf|max:5120']);$sid=$u->role==='student'?$u->id:(int)($d['student_id']??0);abort_unless($allowed->contains($sid),403);$path=$r->hasFile('evidence')?$r->file('evidence')->store('leave-evidence/'.$sid,'public'):null;DB::table('leave_requests')->insert(['student_id'=>$sid,'submitted_by'=>$u->id,'type'=>$d['type'],'date_start'=>$d['date_start'],'date_end'=>$d['date_end'],'reason'=>$d['reason'],'evidence_path'=>$path,'evidence_name'=>$r->file('evidence')?->getClientOriginalName(),'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);return back()->with('status','Pengajuan berhasil dikirim dan menunggu persetujuan.');}
 public function review(Request $r,int $leaveRequest){$u=$r->user();$leave=DB::table('leave_requests')->where('id',$leaveRequest)->first();abort_unless($leave,404);abort_unless($u->role==='admin'||UserDataScope::studentIds($u)->contains($leave->student_id),403);$d=$r->validate(['decision'=>'required|in:approved,rejected','review_note'=>'nullable|string|max:1000']);DB::transaction(function()use($leave,$u,$d){DB::table('leave_requests')->where('id',$leave->id)->update(['status'=>$d['decision'],'reviewed_by'=>$u->id,'review_note'=>$d['review_note']??null,'reviewed_at'=>now(),'updated_at'=>now()]);if($d['decision']==='approved'){for($date=Carbon::parse($leave->date_start);$date->lte(Carbon::parse($leave->date_end));$date->addDay()){$x=DB::table('attendances')->where('student_id',$leave->student_id)->whereDate('date',$date)->first();if(!$x)DB::table('attendances')->insert(['student_id'=>$leave->student_id,'date'=>$date->toDateString(),'status'=>$leave->type,'leave_request_id'=>$leave->id,'created_at'=>now(),'updated_at'=>now()]);elseif(!$x->check_in)DB::table('attendances')->where('id',$x->id)->update(['status'=>$leave->type,'leave_request_id'=>$leave->id,'updated_at'=>now()]);}}else DB::table('attendances')->where('leave_request_id',$leave->id)->whereNull('check_in')->delete();});return back()->with('status',$d['decision']==='approved'?'Pengajuan disetujui.':'Pengajuan ditolak.');}
}
